head.script:
scwin.screenId = "jldfil25210";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25210.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_pwChgConfrmValAppl_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_pwChgConfrmValAppl_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_pwChgConfrmValAppl_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.pwChgConfrmValAppl()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil25210.btn_pwChgConfrmValAppl_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_pwChgConfrmValAppl
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_pwChgConfrmValAppl = async function () {
    const sbmOptions = {
        id: "tx_fn_pwChgConfrmValAppl",
        method: "post",
        action: "/account/password.do?method=issuePwChgConfrmVal",
        ref: "dma_pwChgConfrmValApplReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil25210.tx_fn_pwChgConfrmValAppl" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.pwChgConfrmValAppl
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.pwChgConfrmValAppl = async function () {
    /* sdd-asis-lifecycle:begin fn_pwChgConfrmValAppl — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.passwordForm || { elements: [] });
    $c.util.getComponent('dma_pwChgConfrmValApplReq').set('email', $c.str.trim($c.util.getComponent('ipt_email1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_email2').getValue()));
    if (!$c.cm.fn_CheckEmail($c.util.getComponent('dma_pwChgConfrmValApplReq').get('email'))) {
        return;
    }
    frm.action = '/account/password.do?method=issuePwChgConfrmVal';
    await scwin.tx_fn_pwChgConfrmValAppl();
    /* sdd-asis-lifecycle:end */
};
